const aIRequests = `-- name: AIRequests :many
SELECT r.id, r.workspace_id, r.user_id, r.feature, r.action, r.target_kind, r.target_id, r.target_label, r.provider, r.model, r.input_tokens, r.output_tokens, r.cost_micros, r.outcome, r.outcome_detail, r.duration_ms, r.created_at, r.decided_at, coalesce(u.name, '')::text AS user_name, coalesce(u.email, '')::text AS user_email, coalesce(u.avatar_color, '')::text AS user_color
FROM ai_requests r LEFT JOIN users u ON u.id = r.user_id
WHERE r.workspace_id = $1 AND r.created_at >= $2
  AND ($3::uuid IS NULL OR r.user_id = $3)
  AND ($4::text IS NULL OR r.feature = $4)
  AND ($5::text[] IS NULL OR r.outcome = ANY($5::text[]))
  AND ($6::timestamptz IS NULL OR (r.created_at, r.id) < ($6::timestamptz, $7::uuid))
ORDER BY r.created_at DESC, r.id DESC
LIMIT $8
`

type AIRequestsParams struct {
	WorkspaceID uuid.UUID  `json:"workspaceId"`
	Since       time.Time  `json:"since"`
	UserID      *uuid.UUID `json:"userId"`
	Feature     *string    `json:"feature"`
	Outcomes    []string   `json:"outcomes"`
	Before      *time.Time `json:"before"`
	BeforeID    *uuid.UUID `json:"beforeId"`
	Lim         int32      `json:"lim"`
}

type AIRequestsRow struct {
	ID            uuid.UUID  `json:"id"`
	WorkspaceID   uuid.UUID  `json:"workspaceId"`
	UserID        *uuid.UUID `json:"userId"`
	Feature       string     `json:"feature"`
	Action        string     `json:"action"`
	TargetKind    string     `json:"targetKind"`
	TargetID      *uuid.UUID `json:"targetId"`
	TargetLabel   string     `json:"targetLabel"`
	Provider      string     `json:"provider"`
	Model         string     `json:"model"`
	InputTokens   int32      `json:"inputTokens"`
	OutputTokens  int32      `json:"outputTokens"`
	CostMicros    int64      `json:"costMicros"`
	Outcome       string     `json:"outcome"`
	OutcomeDetail string     `json:"outcomeDetail"`
	DurationMs    int32      `json:"durationMs"`
	CreatedAt     time.Time  `json:"createdAt"`
	DecidedAt     *time.Time `json:"decidedAt"`
	UserName      string     `json:"userName"`
	UserEmail     string     `json:"userEmail"`
	UserColor     string     `json:"userColor"`
}

// The AI activity log, newest first.
func (q *Queries) AIRequests(ctx context.Context, arg AIRequestsParams) ([]AIRequestsRow, error) {
	rows, err := q.db.Query(ctx, aIRequests,
		arg.WorkspaceID,
		arg.Since,
		arg.UserID,
		arg.Feature,
		arg.Outcomes,
		arg.Before,
		arg.BeforeID,
		arg.Lim,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AIRequestsRow{}
	for rows.Next() {
		var i AIRequestsRow
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.UserID,
			&i.Feature,
			&i.Action,
			&i.TargetKind,
			&i.TargetID,
			&i.TargetLabel,
			&i.Provider,
			&i.Model,
			&i.InputTokens,
			&i.OutputTokens,
			&i.CostMicros,
			&i.Outcome,
			&i.OutcomeDetail,
			&i.DurationMs,
			&i.CreatedAt,
			&i.DecidedAt,
			&i.UserName,
			&i.UserEmail,
			&i.UserColor,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const aIRequestsPurge = `-- name: AIRequestsPurge :execrows
DELETE FROM ai_requests WHERE created_at < $1
`

// The activity log keeps 90 days.
func (q *Queries) AIRequestsPurge(ctx context.Context, before time.Time) (int64, error) {
	result, err := q.db.Exec(ctx, aIRequestsPurge, before)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

